/* Reads a whole file; data gets a NUL after the last byte. */
int file_read(const char *path, char **data, size_t *len)
{
	char *buf = NULL;
	size_t n = 0, cap = 0;
	ssize_t got;
	int fd, saved;

	fd = open(path, O_RDONLY);
	if (fd < 0)
		return -1;
	for (;;) {
		if (cap - n < 4096) {
			cap = cap ? cap * 2 : 65536;
			buf = xrealloc(buf, cap + 1);
		}
		got = read(fd, buf + n, cap - n);
		if (got < 0) {
			if (errno == EINTR)
				continue;
			saved = errno;
			free(buf);
			close(fd);
			errno = saved;
			return -1;
		}
		if (got == 0)
			break;
		n += (size_t)got;
	}
	close(fd);
	buf[n] = '\0';
	*data = buf;
	*len = n;
	return 0;
}

/*
 * Starts replacing path with a temporary file in the same directory, so the
 * final rename is atomic. A symlink stays and its target is replaced. The
 * temporary name ends in neither .json nor .jsonl, so Claude Code ignores
 * one left behind by a crash.
 */
struct atomic_file *atomic_open(const char *path, mode_t mode)
{
	struct atomic_file *af;
	struct stat st;
	const char *slash;
	char *target, *dir, *name;
	size_t d;
	int fd, saved;

	if (lstat(path, &st) == 0 && S_ISLNK(st.st_mode)) {
		target = realpath(path, NULL);
		if (target == NULL)
			return NULL;
	} else {
		target = xstrdup(path);
	}
	slash = strrchr(target, '/');
	d = slash != NULL ? (size_t)(slash - target) : 0;
	dir = xmalloc(d + 2);
	if (slash == NULL)
		strcpy(dir, ".");
	else if (d == 0)
		strcpy(dir, "/");
	else {
		memcpy(dir, target, d);
		dir[d] = '\0';
	}
	name = xmalloc(strlen(target) + 16);
	sprintf(name, ".%s.csm-XXXXXX", slash != NULL ? slash + 1 : target);
	af = xmalloc(sizeof *af);
	af->path = target;
	af->tmp = xjoin(dir, name);
	free(dir);
	free(name);
	af->fp = NULL;
	fd = mkstemp(af->tmp);
	if (fd < 0)
		goto fail;
	/* mkstemp creates 0600; the replacement gets the original's mode. */
	if (fchmod(fd, mode & 07777) != 0 ||
	    (af->fp = fdopen(fd, "w")) == NULL) {
		saved = errno;
		close(fd);
		unlink(af->tmp);
		errno = saved;
		goto fail;
	}
	return af;
fail:
	saved = errno;
	free(af->path);
	free(af->tmp);
	free(af);
	errno = saved;
	return NULL;
}

int atomic_write(struct atomic_file *af, const char *data, size_t len)
{
	if (len > 0 && fwrite(data, 1, len, af->fp) != len)
		return -1;
	return 0;
}

static void atomic_free(struct atomic_file *af)
{
	free(af->path);
	free(af->tmp);
	free(af);
}

/*
 * Finishes the replacement. With times the file keeps the original's access
 * and modification times; they are set after the last write, which would
 * otherwise change them again.
 */
int atomic_commit(struct atomic_file *af, const struct timespec times[2])
{
	int saved;

	if (fflush(af->fp) != 0 ||
	    (times != NULL && futimens(fileno(af->fp), times) != 0) ||
	    fsync(fileno(af->fp)) != 0) {
		saved = errno;
		DEBUG_LOG("write %s: %s", af->path, strerror(saved));
		atomic_abort(af);
		errno = saved;
		return -1;
	}
	if (fclose(af->fp) != 0) {
		saved = errno;
		unlink(af->tmp);
		atomic_free(af);
		errno = saved;
		return -1;
	}
	if (rename(af->tmp, af->path) != 0) {
		saved = errno;
		DEBUG_LOG("write %s: %s", af->path, strerror(saved));
		unlink(af->tmp);
		atomic_free(af);
		errno = saved;
		return -1;
	}
	DEBUG_LOG("write %s: ok%s", af->path, times != NULL ?
	    ", times kept" : "");
	atomic_free(af);
	return 0;
}

void atomic_abort(struct atomic_file *af)
{
	fclose(af->fp);
	unlink(af->tmp);
	atomic_free(af);
}

/* Replaces path with data, keeping its mode and, if asked, its times. */
int file_replace(const char *path, const char *data, size_t len,
    int keep_times)
{
	struct atomic_file *af;
	struct timespec times[2];
	struct stat st;
	int saved;

	if (stat(path, &st) != 0)
		return -1;
	platform_file_times(&st, times);
	af = atomic_open(path, st.st_mode);
	if (af == NULL)
		return -1;
	if (atomic_write(af, data, len) != 0) {
		saved = errno;
		atomic_abort(af);
		errno = saved;
		return -1;
	}
	return atomic_commit(af, keep_times ? times : NULL);
}

/*
 * Replaces the program's own file whole, creating its directory when
 * needed; a new file gets mode 0644, an old one keeps its mode.
 */
int file_store(const char *path, const char *data, size_t len)
{
	struct atomic_file *af;
	struct stat st;
	char *dir, *slash;
	int saved;

	dir = xstrdup(path);
	slash = strrchr(dir, '/');
	if (slash != NULL && slash != dir) {
		*slash = '\0';
		if (dir_make(dir, 0700) != 0) {
			saved = errno;
			free(dir);
			errno = saved;
			return -1;
		}
	}
	free(dir);
	af = atomic_open(path, stat(path, &st) == 0 ? st.st_mode : 0644);
	if (af == NULL)
		return -1;
	if (atomic_write(af, data, len) != 0) {
		saved = errno;
		atomic_abort(af);
		errno = saved;
		return -1;
	}
	return atomic_commit(af, NULL);
}

/* Creates dir and its missing parents, like mkdir -p. */
int dir_make(const char *dir, mode_t mode)
{
	struct stat st;
	char *parent;
	const char *slash;
	int r;

	if (mkdir(dir, mode) == 0)
		return 0;
	if (errno == EEXIST)
		return stat(dir, &st) == 0 && S_ISDIR(st.st_mode) ? 0 :
		    (errno = ENOTDIR, -1);
	if (errno != ENOENT)
		return -1;
	slash = strrchr(dir, '/');
	if (slash == NULL || slash == dir)
		return -1;
	parent = xmalloc((size_t)(slash - dir) + 1);
	memcpy(parent, dir, (size_t)(slash - dir));
	parent[slash - dir] = '\0';
	r = dir_make(parent, mode);
	free(parent);
	if (r != 0)
		return -1;
	return mkdir(dir, mode) == 0 || errno == EEXIST ? 0 : -1;
}

static int remove_error;

/* nftw has no context argument; the first error waits here. */
static int remove_one(const char *path, const struct stat *st, int type,
    struct FTW *ftw)
{
	(void)st;
	(void)type;
	(void)ftw;
	if (remove(path) != 0 && remove_error == 0)
		remove_error = errno;
	return 0;
}

/*
 * Removes path and everything below it, children first. FTW_PHYS: a
 * symlink is removed itself, what it points to stays. An error does not
 * stop the rest; -1 with the first errno when anything is left.
 */
int tree_remove(const char *path)
{
	struct stat st;

	remove_error = 0;
	if (nftw(path, remove_one, 16, FTW_DEPTH | FTW_PHYS) != 0 &&
	    remove_error == 0)
		remove_error = errno;
	if (lstat(path, &st) != 0 && errno == ENOENT)
		return 0;
	errno = remove_error != 0 ? remove_error : ENOTEMPTY;
	return -1;
}

/* Copies path to backup with its mode and times, like cp -p. */
int file_backup(const char *path, const char *backup)
{
	struct atomic_file *af;
	struct timespec times[2];
	struct stat st;
	char *data;
	size_t len;
	int saved;

	DEBUG_LOG("backup %s -> %s", path, backup);
	if (stat(path, &st) != 0 || file_read(path, &data, &len) != 0)
		return -1;
	platform_file_times(&st, times);
	af = atomic_open(backup, st.st_mode);
	if (af == NULL || atomic_write(af, data, len) != 0) {
		saved = errno;
		if (af != NULL)
			atomic_abort(af);
		free(data);
		errno = saved;
		return -1;
	}
	free(data);
	return atomic_commit(af, times);
}
